"""Render authored search-intent guides without changing the route timing engine.
Run after build-search-experience.mjs. Editorial estimates are not live timetables.
"""
from pathlib import Path
import json,re,html
ROOT=Path(__file__).resolve().parents[1]
DATE='2026-10-30'
DOMAIN='https://beforeyouflyjapan.com'
def esc(s): return html.escape(s,quote=True)
def link(url,text): return f'<a href="{esc(url)}">{esc(text)}</a>'
def para(s): return '<p>'+s+'</p>'
def section(id,title,body): return f'<section id="{id}"><h2>{title}</h2>{body}</section>'
def table(headers,rows):
 return '<div class="byf-answer-table" role="region" aria-label="'+esc(headers[0])+' comparison" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">'+x+'</th>') if i==0 else '<td>'+x+'</td>' for i,x in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
def sources(items):
 return section('answer-sources','Sources and what these times mean',para('Reviewed 30 October 2026. Opening hours and fees below come from the linked operators. Suggested visit lengths and example journey allowances are our planning estimates, not measured queues, bookable departures or guarantees.')+'<ul>'+''.join('<li>'+link(u,t)+'</li>' for u,t in items)+'</ul>')
HANEDA='https://www.tokyo-haneda.com/en/'
NARITA='https://www.narita-airport.jp/en/'
KIX='https://www.kansai-airport.or.jp/en/'
PAGES={}
def add(path,title,desc,answer,parts,refs,airport=None):
 PAGES[path]={'title':title,'description':desc,'answer':answer,'parts':parts,'refs':refs,'airport':airport}
# 1 and 10: answer the timing question before offering sightseeing.
for code,name,path,extra,refs in [
 ('HND','Haneda','how-early-arrive-haneda-airport',
  [('Terminal 2 international','Follow INTERNATIONAL signs to the international departure area on 3F. Do not assume every international flight uses T3.'),('Terminal 3','Use Haneda Airport Terminal 3 station, then follow Departures to 3F. A train arrival time is not a counter arrival time.')],
  [(HANEDA+'flight/int/dep_step.html','Haneda: international departure procedures'),('https://www.ana.co.jp/en/jp/guide/prepare/airport-guide/international/hnd-terminal-info/','ANA: Terminal 2 and Terminal 3 flight guidance')]),
 ('NRT','Narita','guides/how-early-arrive-narita-airport',
  [('Terminal 1','Narita Airport Terminal 1 station; international counters are on 4F. Match the wing and counter to your flight.'),('Terminal 2','Airport Terminal 2 station; international counters are on 3F.'),('Terminal 3','Airport Terminal 2 station is also the rail stop for T3. The airport quotes about 13 minutes from its ticket gates to the T3 2F information counter; reaching your airline and completing procedures take additional time.')],
  [(NARITA+'airportguide/inter-dep/','Narita: official arrival guidance and departure floors'),('https://www.narita-airport.jp/ja/access/shuttlebus/walking-through/','Narita: T2 station to T3 walking route (Japanese)'),(NARITA+'access/shuttlebus/','Narita: terminal shuttle routes and ride times')]),
 ('KIX','Kansai (KIX)','guides/how-early-arrive-kansai-airport',
  [('Terminal 1','From Kansai-airport Station, follow signs into T1 and up to international departures on 4F.'),('Terminal 2','From the station, reach the Aeroplaza 1F shuttle stop. The free shuttle ride is 7–9 minutes; walking to the stop, waiting and reaching your counter are extra. Do not treat station arrival as T2 arrival.')],
  [(KIX+'flight/route/transit','KIX: terminal floors and connections'),(KIX+'access/t2','KIX: Terminal 2 shuttle stop and ride time'),(KIX+'flight/route/t2_dep','KIX: Terminal 2 departure procedures')])]:
 answer=f'For an international flight from {name}, use <strong>3 hours before departure at the correct terminal, with your bags collected</strong> as our conservative planning starting point. This is Before You Fly’s allowance, not a universal airline deadline. Follow any earlier instruction from your airline.'
 if code=='NRT': answer+=' Narita’s official guidance says at least 2 hours before departure, with timing dependent on the airline’s check-in opening time. Our extra hour provides room for an unfamiliar airport and changes to the journey.'
 parts=[section('which-time','Which time are you actually trying to meet?',table(['Time','What it means'],[
 ('Airport-ready target','You have reached the correct departure terminal, collected stored bags and can begin the airline procedures.'),('Check-in / bag-drop deadline','The last time your airline accepts the required procedure. Online check-in does not remove baggage or document checks.'),('Boarding deadline','You must be at the gate by the airline’s stated time. It can be well before takeoff; airport shopping comes after essential procedures.')])+para('Domestic flights and flight-to-flight connections need their own airline guidance. This page is for international passengers arriving from the city. A three-hour allowance does not mean your airline opens its counter three hours before every flight.')),
 section('terminal','Get to the right terminal, not just the airport station',table(['Your terminal','Where the journey really ends'],extra)),
 section('leave-by','Work backwards all the way to your last stop',para('<strong>Sightseeing ends = flight time − airport allowance − complete journey − luggage pickup.</strong> The complete journey includes walking, waiting, riding, changes and the walk to the counter. Add a separate disruption margin if your transport estimate does not already include one.')+table(['Worked example: 21:00 flight','Time / allowance'],[
 ('Ready at the departure terminal','18:00 — using our 3-hour planning target'),('Complete journey after collecting bags','90 minutes in this example: 10 walking + 15 waiting + 45 riding + 20 terminal navigation'),('Leave the luggage collection point','16:30'),('Collect stored bags','16:10–16:30 — allow 20 minutes in this example'),('End sightseeing','16:10, only if you are already at the luggage location. End earlier by the full detour if your bags are elsewhere.')])+para('Those 90 and 20 minutes are illustrative inputs, not a route recommendation. Replace them with the itinerary from your exact starting point and your actual storage arrangement. Do not add walking twice if a door-to-door route already includes it.')),
 section('situations','How the plan changes with your situation',table(['Your situation','A practical decision'],[
 ('Hand luggage only and checked in online','Keep the airport allowance until document checks and security requirements are clear. Use saved time for a relaxed airport meal.'),('Checked bags or a hotel pickup','Build the pickup into the route before choosing a final attraction. A hotel across town can cost more time than the attraction itself.'),('Children, step-free travel or assistance','Use a longer personal allowance for lifts, rest and assistance arrangements. Do not rely on the example’s short walking stages.'),('Rail disruption or a wrong-terminal discovery','Drop the optional stop. Recalculate the whole remaining route; a different service or terminal transfer can erase the spare time.')]))]
 if code=='HND':
  parts.append(section('after-midnight','A 00:30 flight means going to the airport the previous evening',para('For a flight dated <strong>31 October at 00:30</strong>, a three-hour target is <strong>30 October at 21:30</strong>. With the example 90-minute journey and 20-minute bag pickup, sightseeing ends at 19:40 on 30 October. Enter the actual departure date in the planner; do not enter 30 October at 00:30.')+para(link('/guides/haneda-airport-open-24-hours/','Read the overnight and early-morning guide')+' · '+link('/guides/haneda-terminal-3-departure-guide/','Find your way around Terminal 3'))))
 elif code=='NRT':
  parts.append(section('city-choice','Tokyo or Narita town for the last stop?',para('A short rail ride from Narita town still needs a station approach, a wait, baggage collection and the correct terminal. Tokyo offers more choice but usually a longer airport journey. Choose one starting area; do not add a Narita town visit on top of a full Tokyo day simply because it is near the airport.')+para(link('/guides/narita-departure-day/','Compare Tokyo, Narita town and staying at the airport')+' · '+link('/places/narita-omotesando/','A short Narita Omotesando visit'))))
 else:
  parts.append(section('city-choice','Choose the station that matches your airport route',para('Nankai Namba and JR Osaka are different departure points. Use the route from the station you will actually reach, including your hotel or locker detour. Rinku Town is closer to the airport, but shopping bags and a T2 shuttle still need time. For an early flight, compare the first available service with the terminal-ready target before choosing a city hotel departure time.')+para(link('/guides/kansai-departure-day/','Compare Namba, Umeda, Rinku and KIX')+' · '+link('/guides/after-hotel-checkout-osaka/','Plan the day after Osaka hotel checkout'))))
 add(path,f'How Early to Arrive at {name} for an International Flight',f'Plan your {name} arrival with terminal directions, baggage pickup, a worked leave-by example and clear airline-deadline guidance.',answer,parts,refs,code)
# 2: terminal orientation, with explicit landside/airside distinctions.
add('guides/haneda-terminal-3-departure-guide','Haneda Terminal 3 Departures: Floors, Map & What to Do',
 'Find Haneda T3 check-in on 3F, see what is before or after security, and plan food, luggage and lounge time without missing your flight.',
 '<strong>International departures at Haneda Terminal 3 start on 3F.</strong> Go to your airline’s counter or the required departure procedure first. Edo Ko-ji and the observation deck are on the public side; lounges and gate-area shops may be beyond security. Confirm that your flight uses T3: some international services use T2.',[
 section('floor-map','A floor guide for the decisions you will make',table(['Place','Use it for','Before or after security?'],[
 ('3F departure lobby','Flight displays, airline check-in and the route to security','Public side until you pass security'),('4F Edo Ko-ji','A meal or a short browse when your procedures allow it','Public side'),('5F observation deck','A short aircraft view; weather restrictions can close it','Public side'),('International departure area','Gate, duty-free shopping and eligible lounges','After security and departure immigration')])+para(link(HANEDA+'floor/terminal3/','Open the official interactive T3 floor guide'))),
 section('station','From the train to the airline counter','<ol><li>Leave the train at <strong>Haneda Airport Terminal 3</strong>. T1/T2 is a different stop.</li><li>Follow <strong>Departures / 3F</strong>, using lifts if you have a stroller or large suitcase.</li><li>Read the flight display for your flight number and counter. Counter assignments can change.</li><li>Complete the airline’s check-in, baggage and document requirements, then follow security and departure immigration signs.</li><li>Find your gate and boarding deadline before settling down for food or shopping.</li></ol>'+para('Allow a station-to-counter stage in your journey: platform exit, lifts and locating the airline all take time. We do not give one guaranteed walking time for every train exit and counter. '+link('https://www.haneda-tokyo-access.com/en/haneda-airport/to-terminal.html','Keikyu’s station-to-terminal diagrams')+' show the approach.')),
 section('spare-time','Choose one extra stop, after you know what time is free',table(['Time genuinely spare before your next required procedure','Our suggestion'],[
 ('15–20 minutes','Stay on the departure floor. Find a toilet or drink nearby; avoid another floor or a queue.'),('30–45 minutes','If still on the public side, choose a short deck visit or browse. These are visit allowances, not time before takeoff.'),('60 minutes or more','A seated meal can fit if the queue and service time leave room for the next procedure. Choose an open restaurant in the correct area.')])+para('Do not subtract these activities from check-in or security time. If already airside, use gate-area facilities; do not plan to return to Edo Ko-ji for dinner. Restaurant opening hours vary even though the terminal is open all night.')),
 section('bags-lounge','Stored bags and lounges: two easy mistakes to avoid',para('Collect a public-area locker bag before going through departure procedures. The airport’s locker listing gives terminal locations, sizes and charges; availability is not guaranteed. Keep the receipt or locker details accessible rather than packed away.')+para('TIAT LOUNGE is not a public waiting room for anyone arriving at the airport. Entry depends on its location, your departure eligibility and the accepted airline, card or paid-access conditions. Do not assume a card accepted at a domestic POWER LOUNGE also grants TIAT access. A lounge listing’s opening hours do not guarantee admission or space.')+para(link(HANEDA+'service/facilities/coin_locker.html','T3 locker locations and charges')+' · '+link(HANEDA+'service/facilities/lounge.html','Official lounge access conditions'))),
 section('next','If your counter is not open yet',para('Stay on the public side, keep bags with you or use suitable storage, and choose a nearby open facility. For an overnight wait, the terminal’s entry and overnight rules matter as well as the flight time.')+para(link('/guides/haneda-airport-open-24-hours/','What stays open overnight at Haneda')+' · '+link('/how-early-arrive-haneda-airport/','Set your Haneda arrival and city leave-by times')))
 ],[(HANEDA+'flight/int/dep_step.html','Haneda: departure procedures and 3F counters'),(HANEDA+'floor/terminal3/','Haneda: terminal floor guide'),(HANEDA+'service/facilities/observation_deck.html','Haneda: observation-deck hours and weather restrictions'),(HANEDA+'service/facilities/lounge.html','Haneda: lounge access conditions')],'HND')
# 3: do not promise unrestricted overnight accommodation.
add('guides/haneda-airport-open-24-hours','Is Haneda Airport Open 24 Hours? Overnight & Early Flights',
 'Understand Haneda T3 overnight rules, T1/T2 opening hours, transport limits and which date to use for a flight after midnight.',
 '<strong>Terminal 3 is generally open 24 hours; that does not apply to every Haneda terminal or service.</strong> The airport says overnight stays inside T3 are for people who have used or will use international flights. A domestic-only early flight is not a reason to assume you can sleep there.',[
 section('terminal-hours','What is open, and what is not?',table(['Area or service','What the official guidance means for you'],[
 ('T3 terminal building','Generally open 24 hours. Overnight eligibility is restricted to international-flight users under the airport’s rules.'),('T1 and T2 domestic areas','Generally 05:00–24:00, with lobby closure tied to the last flights. You generally cannot stay in the lobby after it closes.'),('T2 international departures','Opens at 05:00; the departure lobby remains open until after the last departure. Do not use T3’s 24-hour rule for T2.'),('Airline counters and security','Their operation depends on the flight and facility. An open terminal does not mean you can check a bag or enter airside at any hour.'),('Restaurants, lockers and transport','Each has its own hours or access conditions. Trains do not run continuously through the night.')])) ,
 section('overnight','Arriving the evening before an early flight',para('If you are eligible to wait in T3 overnight, expect an airport waiting area, not a reserved bed. Keep your flight details available and follow staff instructions. Seats, quiet surroundings and charging points cannot be guaranteed. For reliable rest, especially with children, compare a bookable hotel and its actual early-morning access to your departure terminal.')+para('The Royal Park Hotel Tokyo Haneda is listed at T3; the airport hotel directory also lists other terminal properties. Choose by access to your departure terminal, not the word “airport” in the hotel name. A shuttle that starts after your check-in target will not solve an early-flight journey. '+link(HANEDA+'service/facilities/hotel.html','See the airport’s hotel directory')+'.')),
 section('midnight','A flight just after midnight belongs to the next date',para('<strong>Ticket: 31 October, 00:30. Airport-ready target: 30 October, 21:30.</strong> Travel to the airport on the evening of 30 October. If you travel there on the evening of 31 October, the flight has already left.')+para('In the planner, enter 31 October at 00:30 as the flight and your actual free time on 30 October. All times on this site use Japan Standard Time (JST). The date is as important as the clock time.')),
 section('transport','When the first or last train does not fit',para('For a 06:30 flight, our three-hour planning target would be 03:30. Do not assume a morning train can reach it. Compare the airport-access timetable with your terminal and airline instructions, then choose an eligible overnight wait, suitable accommodation or a prearranged road journey. Road services also need availability and a real pickup time.')+para(link(HANEDA+'access/train/','Train and monorail access')+' · '+link(HANEDA+'access/bus/','Airport bus access')+' · '+link(HANEDA+'access/taxi/','Taxi access information'))),
 section('food','A simple plan for food and luggage',para('Eat before the late-night journey if your preferred terminal restaurant will be closed. Keep medication, baby supplies, documents and a charger with you until baggage drop actually opens. If using a locker or staffed counter, choose one you can reach at the collection time; a storage service on the wrong side of security is not a usable plan.')+para('T3’s observation deck is listed as open 24 hours, subject to weather closure. It is an optional short view, not an indoor sleeping area or a substitute for rest.')),
 section('next','Plan the next morning without a rushed terminal change',para(link('/guides/haneda-terminal-3-departure-guide/','T3 floors, departure procedures and public-area facilities')+' · '+link('/how-early-arrive-haneda-airport/','Calculate when to leave the city')))
 ],[(HANEDA+'faq/terminal_details.html','Haneda FAQ: terminal hours and overnight eligibility'),(HANEDA+'service/facilities/hotel.html','Haneda: airport hotels'),(HANEDA+'service/facilities/observation_deck.html','Haneda: observation deck')],'HND')
# 4–9: focused additions to retained place guides, photos and flight-aware routes.
add('places/tsukiji-outer-market','Tsukiji Outer Market: Hours, Map & a Short Food Walk',
 'Find Tsukiji Outer Market, choose a useful visiting time and a short food walk, and understand closures, luggage and the difference from Toyosu.',
 '<strong>Tsukiji Outer Market is the food-shopping district in Tsukiji, not the wholesale market at Toyosu.</strong> Visit for small food shops and a meal. There is no single opening time for the whole district; choose an open shop and a date from the market calendar.',[
 section('market-hours','Will there be something to eat when you arrive?',table(['When you can visit','What to plan'],[
 ('Morning to early afternoon','Our suggested visiting window is around 09:00–14:00, when a short food visit is more practical. Individual shops can open earlier or close sooner.'),('Sunday, holiday or a marked market closure day','Some shops may operate, but do not expect the full weekday choice. Use the official calendar and your chosen shop’s own listing.'),('Late afternoon or evening','A street can remain accessible after many stalls close. For a final dinner, consider Ginza or your airport rather than assuming the market serves late.')])+para(link('https://www.tsukiji.or.jp/english/calendar/','Market calendar')+' · '+link('https://www.tsukiji.or.jp/english/shoplist/','Official shop directory'))),
 section('food-walk','A 60–90 minute food visit, not a queue marathon',para('Start with one thing you actually want to eat: a seafood bowl, tamagoyaki or a small snack. Give the first part of the visit to that choice, then browse one lane for tea, pantry ingredients or kitchen goods. Keep the final 10–15 minutes for finding your return route. This is time in the market only; the airport journey and luggage are extra.')+para('If a queue threatens your leave-by time, choose another open shop. Eating one good meal is more useful than spending the whole stop waiting for a famous counter. Follow each shop’s rules for where to eat and return rubbish to the appropriate collection point.')),
 section('market-map','Find the outer market and keep the return simple',para('Use Tsukiji Station on the Hibiya Line or Tsukijishijo on the Oedo Line as your route anchor. The market’s official access map places the food streets and information centre; choose the station that matches your onward journey rather than simply the closest entrance.')+para(link('https://www.tsukiji.or.jp/english/access/','Official market access map')+' · '+link('/places/toyosu/','Looking for Toyosu instead?'))),
 section('market-bags','Where to ask about bags and an open shop',para('Plat Tsukiji provides maps, English-language assistance and coin lockers, including larger sizes. Its English listing gives information-counter hours of 08:00–14:00 on weekdays/Saturdays and 10:00–14:00 on Sundays, holidays and market closure days, with year-end closures. Special notices can change these hours. Do not assume locker access lasts all evening, and do not count on an empty compartment.')+para('If there is no suitable storage, choose a meal near your departure station or collect your hotel bags and go to the airport. Narrow shopping lanes are a poor place to spend your final hour managing a suitcase.'))
 ],[('https://www.tsukiji.or.jp/english/calendar/','Market association: calendar'),('https://www.tsukiji.or.jp/english/plattsukiji/','Plat Tsukiji: services and published hours'),('https://www.tsukiji.or.jp/english/access/','Market association: access map')])
add('places/tokyo-tower','Tokyo Tower: Location, Tickets & Time for a Short Visit',
 'Find Tokyo Tower in Shibakoen, compare an exterior stop with the Main Deck, and see prices, hours and practical time allowances before a flight.',
 '<strong>Tokyo Tower is in Shibakoen, Minato City, not Ginza.</strong> An exterior photo stop and a trip up to the observation deck are different visits. Choose which matters to you before committing to a queue.',[
 section('tower-choices','Choose the view you have time for',table(['Visit','Cost and time to plan'],[
 ('Exterior from public streets','No observation ticket needed. Allow roughly 20–30 minutes locally for views and photos; walking from the station is extra.'),('Main Deck, 150 m','Adult ¥1,500; high-school ¥1,200; elementary/junior-high ¥900; age 4+ ¥600. Allow roughly 60–90 minutes for the visit, with additional time if queues are long.'),('Top Deck Tour, 150 m + 250 m','Adult ¥3,300 online or ¥3,500 at the counter on the reviewed tariff. It includes the Main Deck. Choose only when the booked slot and the full visit fit your airport deadline.')])+para('These visit lengths are editorial allowances, not operator-guaranteed durations. A timed ticket does not make the airport journey shorter.')),
 section('tower-hours','Opening hours and when to skip the ascent',para('The Main Deck is listed as 09:00–23:00, with last admission at 22:30; crowding can bring admission forward. The Top Deck Tour is listed as 09:00–22:45, last tour 22:15, and can be suspended for weather or operational reasons.')+para('If visibility is poor or the queue uses up the spare time, enjoy the tower from outside and keep the journey comfortable. Do not add a second paid attraction simply because you have already reached the building.')),
 section('tower-location','Use Shibakoen as the location, not Ginza',para('The address is 4-2-8 Shibakoen, Minato City. Compare the official approaches from Akabanebashi, Onarimon, Kamiyacho and the Hamamatsucho corridor. The nearest station for arrival may not be the best one for your airport return. Walking, crossings and station entrances belong in the journey time.')+para(link('https://en.tokyotower.co.jp/access/','Official station approaches and access map')+' · '+link('/places/hamamatsucho-zojoji/','A nearby Zojoji and Hamamatsucho alternative'))),
 section('tower-bags','Keep a short stop short',para('Store large luggage on the airport-return route before climbing or joining a queue. If using a stroller or travelling with someone who needs lifts, use the operator’s accessibility guidance and allow longer for the station approach. A photo outside followed by a relaxed meal can be a better final memory than rushing down from the deck.'))
 ],[('https://en.tokyotower.co.jp/fee/','Tokyo Tower: current ticket categories and opening hours'),('https://en.tokyotower.co.jp/access/','Tokyo Tower: address and station access')])
add('places/asakusa-sensoji','Sensoji & Asakusa: Opening Hours and a Short Temple Walk',
 'See when Sensoji’s main hall opens, why Nakamise hours differ, and how to plan an early, daytime or evening Asakusa visit before your flight.',
 '<strong>Asakusa has no single opening time.</strong> Sensoji’s main hall opens 06:00–17:00 from April to September and 06:30–17:00 from October to March. Nakamise shops and other temple facilities keep separate hours.',[
 section('asakusa-hours','Choose the visit you want, then choose the time',table(['Your visit','What to expect'],[
 ('Early morning','A temple-focused visit can work before the shops open. Do not promise yourself breakfast or souvenir shopping along a fully open Nakamise.'),('Daytime','Best for combining the main hall with shops that are open. Leave room for crowds at Kaminarimon and the approach.'),('After 17:00','The main hall is closed. Treat this as an exterior and neighborhood visit, with shop-by-shop availability; it is not the same temple visit as daytime.')])+para('Main-hall hours are from Sensoji itself. Special events, access restrictions and the hours of other halls can differ.')),
 section('temple-walk','A simple route: Kaminarimon → Nakamise → the main hall',para('Allow about 60–90 minutes locally for a compact temple walk and a little browsing, rather than trying to cover all of Asakusa. Pause at Kaminarimon, walk along Nakamise without blocking shop fronts, then continue through Hozomon toward the main hall. Keep a shorter version if the crowd is slow. The existing flight-aware planner may allocate a longer visit; use its complete route for your departure decision.')+para('For an early visit, put the temple first and have breakfast elsewhere if shops are closed. For a shopping visit, avoid using the hall’s early opening time as evidence that Nakamise will be ready for you.')),
 section('asakusa-stations','Asakusa Station can mean a different entrance',para('Ginza Line, Toei Asakusa Line, Tobu and Tsukuba Express services do not all use the same platforms or exits. Choose the station for your onward airport train and save its location before walking. A map pin simply labelled “Asakusa” is not a complete return route.')+para('Large bags and crowded approaches make this less comfortable. Leave luggage on your return corridor and include collection time. With a stroller or limited mobility, keep the route to the main approach and use accessible station exits.')),
 section('asakusa-alternative','When the visit no longer fits',para('If the main hall has closed and that was your reason for coming, choose an evening neighborhood walk only if you still want it. If time is tight, skip extra side streets and head back to the correct station. '+link('/places/ueno-ameyoko/','Ueno and Ameyoko')+' is an alternative area, not an automatic extra stop to add on top.'))
 ],[('https://www.senso-ji.jp/visit/','Sensoji: official main-hall opening and closing times (Japanese)'),('https://www.senso-ji.jp/english/','Sensoji: English temple guide'),('https://www.gotokyo.org/en/destinations/eastern-tokyo/asakusa/','GO TOKYO: Asakusa area and access')])
add('places/shiodome','Shiodome Pedestrian Deck: Map & a Short Shimbashi Walk',
 'Navigate Shiodome’s elevated walkways from Shimbashi, choose a short loop and understand station levels, rain alternatives and airport-return time.',
 '<strong>Shiodome’s pedestrian deck is a network of elevated walkways between buildings, not a single ticketed observation deck.</strong> It suits a short architecture walk near Shimbashi. Keep one station entrance as your return point so the different levels do not turn a quick stop into a detour.',[
 section('deck-start','Start from a named building, not an anonymous deck pin',para('From JR Shimbashi, use the Shiodome side and aim for Shiodome City Center. The building’s operator lists a roughly three-minute walk from JR’s Shiodome exit, two minutes from the Toei Asakusa Line’s Shiodome/Shiosite exit and one minute from the listed Oedo Line approach. These are building access estimates, not a promise for a whole sightseeing loop.')+para(link('https://www.shiodome-cc.com/en/','Open the operator’s station approaches and area map')+'. Use the map’s building names and follow the signs for public walkways; railway platforms, underground corridors and deck level are not interchangeable.')),
 section('deck-loop','A 30–45 minute walk with one clear way back','<ol><li>Find Shiodome City Center and note your arrival entrance.</li><li>Take the signed public walkway toward the surrounding Shiodome buildings. Choose a short outward section rather than crossing the whole district.</li><li>Pause for the contrast between the glass towers and the railway-side streets.</li><li>Return to the same station approach, leaving the final 10 minutes for orientation.</li></ol>'+para('This is a suggested local visit allowance, excluding the train to the airport and bags. Follow current closures and signs; it is not a surveyed step-free route. Do not enter offices or private terraces looking for a continuous path.')),
 section('deck-rain','Rain, luggage or a tired traveller?',para('Choose a café or meal in an open building near your return station. Indoor connections can help, but not every walkway is covered or accessible all night. With a large case or stroller, use signed lifts and shorten the loop. If you cannot readily find the next accessible connection, return along the route you know.')+para('A high-floor restaurant is a separate activity with its own hours, prices and possibly reservations. It is not the same thing as free access to the pedestrian deck.')),
 section('deck-airport','Do not mistake a fast train ride for the whole journey',para('Shimbashi offers useful airport corridors, but the train’s destination and stopping pattern matter. Include the walk back, reaching the platform, waiting, luggage pickup and terminal navigation. A short ride advertised by a building or rail operator is not your door-to-counter allowance. '+link('/how-early-arrive-haneda-airport/','Use the Haneda arrival guide')+' to keep those stages visible.'))
 ],[('https://www.shiodome-cc.com/en/','Shiodome City Center: access times, area map and public facilities'),('https://www.japan.travel/en/spot/368/','JNTO: Shiodome neighborhood')])
add('places/naritasan-shinshoji','Naritasan Shinshoji: A Short Temple Visit Before a Flight',
 'Plan a focused Naritasan Shinshoji visit with a station approach, temple priorities, luggage advice and a realistic return to Narita Airport.',
 '<strong>Naritasan Shinshoji is in Narita town, not inside Narita Airport.</strong> Choose it for the temple buildings and atmosphere. Use a separate allowance for the station approach and airport return; being nearby does not mean a spare hour is enough.',[
 section('temple-priority','Make the temple the reason for the stop',para('For a first short visit, focus on the entrance, the main temple area and the architecture around it. Give yourself roughly 45–60 minutes within the temple area, excluding the walk from the station. Do not make the park, a long meal and every hall compulsory parts of the same stop.')+para('Religious services are part of a working temple. If attending a ceremony matters to you, use the temple’s current schedule and allow time to arrive quietly; do not assume one starts whenever you arrive. Follow photography and access signs.')),
 section('temple-approach','The walk starts in town',para('The temple’s access page lists a ten-minute walk from JR Narita or Keisei Narita. For an unfamiliar visitor using the shopping street, we suggest budgeting 20–30 minutes each way for navigation, slopes, crossings and pauses. That is our more generous allowance, not a different official distance.')+para('Stairs and sloping approaches can make bags or a stroller awkward. With mobility needs, establish the accessible route before setting off and keep the visit compact. Save the station name for the operator you will use on the return.')),
 section('temple-time','What a compact visit actually consumes',table(['Stage','Illustrative allowance'],[
 ('Station → temple','20–30 minutes'),('Temple area','45–60 minutes'),('Temple → station','20–30 minutes'),('Subtotal in town','85–120 minutes, before luggage, train waiting, the airport ride and terminal navigation')])+para('This subtotal is not “time needed before takeoff.” Protect the airline and airport time separately. If the total does not fit, choose an airport meal instead of compressing all stages.')),
 section('temple-meal','If you also want the shopping street',para(link('/places/narita-omotesando/','Narita Omotesando’s food-and-shopping guide')+' covers the street and a shorter food-first option. A queue for eel can use the time intended for the temple, so choose your main purpose before joining it. '+link('/guides/how-early-arrive-narita-airport/','The Narita departure guide')+' explains the station and terminal stages, including T3.'))
 ],[('https://www.naritasan.or.jp/access/','Naritasan: official station approach (Japanese)'),('https://www.naritasan.or.jp/','Naritasan: current notices and ceremony information (Japanese)'),('https://www.japan.travel/en/spot/1549/','JNTO: Naritasan temple and Omotesando')])
add('places/narita-omotesando','Narita Omotesando: Food, Shopping & Time Before a Flight',
 'Choose a short Narita Omotesando food walk, leave time for the uphill return and luggage, and decide whether a temple visit still fits.',
 '<strong>Narita Omotesando is the shopping street leading from the Narita station area toward Naritasan.</strong> This is Narita in Chiba, not Tokyo’s Omotesando near Harajuku. Come for a short street walk, food or a few gifts; shop hours differ.',[
 section('street-choice','Pick one: a meal, a browse or the temple',table(['What you want','A useful way to spend the stop'],[
 ('A short browse','Allow 45–60 minutes for a modest out-and-back section from the station area. Choose one or two shops and turn around before the deadline.'),('A seated meal','Allow around 60–90 minutes locally, more if there is a queue. Ask about the wait before committing; a popular eel restaurant is not a quick snack stop.'),('Naritasan as well','Use the separate temple guide and add the approach, visit and return. Do not count a temple visit as free time inside the meal allowance.')])+para('These are editorial visit allowances, excluding storage and the airport trip. You do not need to reach the temple gate to enjoy the street.')),
 section('street-return','The return walk deserves its own time',para('The approach slopes toward the temple area, so the return toward the stations can feel longer, particularly with bags or after lunch. Save your JR Narita or Keisei Narita entrance and turn back while there is still time to collect luggage and wait for the right train.')+para('Narita town and Narita Airport are different stops. Choose an actual airport-bound service and the station for your departure terminal. For T3, include the walk or shuttle after arriving at Airport Terminal 2 station.')),
 section('street-hours','Avoid arriving for a meal after the kitchen has closed',para('The street has no universal last order or closing time. Select an open restaurant before walking the full length, and treat browsing as optional if your visit is late in the day. A temple opening notice does not establish the opening hours of neighboring shops.')+para('Budget for the meal you choose rather than treating every restaurant as the same price. The street walk itself needs no general admission ticket; food and purchases are extra.')),
 section('street-bags','Travel light, and keep one fallback',para('Use a suitable station-side locker if available, on the same operator’s side as your return. Keep enough time for collection, not just the train. If bags cannot be stored or the restaurant wait is long, shorten the street walk and eat at the airport.')+para(link('/places/naritasan-shinshoji/','Choose the temple-focused visit instead')+' · '+link('/guides/how-early-arrive-narita-airport/','Work backwards from your Narita flight')+' · '+link('/places/omotesando/','Looking for Omotesando in Tokyo?')))
 ],[('https://www.japan.travel/en/spot/1549/','JNTO: Narita Omotesando and Naritasan'),('https://www.naritasan.or.jp/access/','Naritasan: station access (Japanese)'),(NARITA+'access/shuttlebus/','Narita Airport: terminal transfers')])
add('places/nihonbashi','Nihonbashi: Meaning, Location & a Short Tokyo Walk',
 'Find Nihonbashi Bridge, understand the name and choose a short history-and-food walk near Tokyo Station with time left for the airport.',
 '<strong>Nihonbashi means “Japan Bridge.”</strong> It names both the historic bridge and the surrounding Tokyo district, northeast of Tokyo Station. If you want to see the bridge, use the bridge as your map destination rather than a department store or a broad neighborhood pin.',[
 section('bridge-story','Why stop at this bridge?',para('Nihonbashi became the starting point of the five major roads of Edo. The bridge still marks the reference point used for distances from Tokyo. That makes it a small, tangible way to understand the old city: look at the bridge and river, then the commercial streets that grew around them.')+para('It is a city bridge, not a large admission-based attraction. A short stop works best when you combine it with one nearby shop or a tea break, rather than expecting a long sightseeing complex.')),
 section('bridge-walk','A 45–60 minute bridge-and-shop visit',para('Start at Nihonbashi Bridge, allow 10–15 minutes to see it from the public pavement, then choose one nearby food shop or department-store food floor for browsing. Keep the last 10–15 minutes for returning to your chosen station. These are local visit allowances; a seated meal, a queue or a long Tokyo Station walk needs extra time.')+para('For a rainy day, give more time to an open indoor shop and less to the bridge. Food floors are not always seating areas, so decide where you will eat before buying a full meal.')),
 section('bridge-access','Nihonbashi, Mitsukoshimae or Tokyo Station?',para('Nihonbashi and Mitsukoshimae stations serve different parts of the district. Tokyo Station is another option, but leaving its platforms and crossing to the Yaesu side is part of the walk, not zero-time access. Choose the station that matches your arrival and airport return.')+para(link('https://www.gotokyo.org/en/spot/44/index.html','Official tourism guide: bridge location and access')+' · '+link('https://www.google.com/maps/search/?api=1&query=Nihonbashi+Bridge+Tokyo','Find Nihonbashi Bridge on the map'))),
 section('bridge-next','When this is a good last stop',para('Choose it when you want a compact city walk and can leave your luggage along the return route. With bags still at Tokyo Station, keep collection in the plan. If you already feel tired, one nearby café is enough; the bridge does not need an ambitious itinerary around it.')+para(link('/places/tokyo-station-marunouchi/','Compare a Tokyo Station and Marunouchi stop')+' · '+link('/guides/luggage-before-flight-japan/','Choose storage that avoids a second cross-city journey')))
 ],[('https://www.gotokyo.org/en/spot/44/index.html','GO TOKYO: Nihonbashi Bridge and road origin'),('https://www.japan.travel/en/destinations/kanto/tokyo/ginza-and-nihombashi/','JNTO: name and neighborhood'),('https://www.gotokyo.org/en/destinations/central-tokyo/nihombashi/','GO TOKYO: district stations and attractions')])

# Rendering: preserve retained photos, practical sources and tested planner links.
def update_meta(text,path,row):
 title=esc(row['title']); desc=esc(row['description']); url=DOMAIN+'/'+path+'/'
 text=re.sub(r'<title>.*?</title>',f'<title>{title} — Before You Fly</title>',text,flags=re.S)
 for attr,val in [('name="description"',desc),('property="og:title"',title),('property="og:description"',desc),('property="og:url"',url)]:
  text=re.sub(r'(<meta '+attr+r' content=")[^"]*',lambda m:m[1]+val,text)
 text=re.sub(r'(<link rel="canonical" href=")[^"]*',lambda m:m[1]+url,text)
 text=re.sub(r'<h1([^>]*)>.*?</h1>',lambda m:'<h1'+m[1]+'>'+title+'</h1>',text,flags=re.S)
 text=re.sub(r'<!-- BYF:query-schema -->.*?<!-- /BYF:query-schema -->','',text,flags=re.S)
 schema={'@context':'https://schema.org','@type':'Article','headline':row['title'],'description':row['description'],'dateModified':DATE,'mainEntityOfPage':url,'author':{'@type':'Organization','name':'Before You Fly','url':DOMAIN+'/about/'}}
 # Replace existing place Article with refreshed metadata, retaining breadcrumbs.
 def jsonld(m):
  try: obj=json.loads(m[1])
  except ValueError:return m[0]
  if obj.get('@type')=='Article': return ''
  if obj.get('@type')=='BreadcrumbList':
   obj['itemListElement'][-1].update(name=row['title'],item=url)
   return '<script type="application/ld+json">'+json.dumps(obj,ensure_ascii=False)+'</script>'
  return m[0]
 text=re.sub(r'<script type="application/ld\+json">(.*?)</script>',jsonld,text,flags=re.S)
 text=text.replace('</head>','<!-- BYF:query-schema --><script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script><!-- /BYF:query-schema --></head>')
 if '/assets/query-guides.css' not in text:text=text.replace('</head>','<link rel="stylesheet" href="/assets/query-guides.css?v=20261030-1"></head>')
 return text

template=(ROOT/'guides/how-early-arrive-narita-airport/index.html').read_text()
for path,row in PAGES.items():
 file=ROOT/path/'index.html'
 text=file.read_text() if file.exists() else template
 text=re.sub(r'<!-- BYF:query-answer -->.*?<!-- /BYF:query-answer -->','',text,flags=re.S)
 nav='<nav class="byf-answer-nav" aria-label="On this page">'+''.join(link('#'+re.search(r'id="([^"]+)"',part)[1],re.search(r'<h2>(.*?)</h2>',part)[1]) for part in row['parts'])+'</nav>'
 body='<div class="byf-query-content"><div class="byf-answer-intro"><p class="byf-kicker">YOUR VISIT, EXPLAINED</p>'+para(row['answer'])+'</div>'+nav+''.join(row['parts'])+sources(row['refs'])+'</div>'
 if path.startswith('places/'):
  text=text.replace('<!-- /BYF:visit-nav -->','<!-- /BYF:visit-nav --><!-- BYF:query-answer -->'+body+'<!-- /BYF:query-answer -->')
 else:
  cta=para(link('/?airport='+row['airport']+'#planner','Plan from my flight time →'))
  main='<main id="main-content"><nav class="byf-breadcrumbs" aria-label="Breadcrumb">'+link('/','Home')+' / '+link('/guides/','Guides')+' / '+esc(row['title'])+'</nav><article class="byf-info-page byf-query-guide"><p class="byf-kicker">DEPARTURE-DAY GUIDE</p><h1>'+esc(row['title'])+'</h1>'+body+'<section class="byf-guide-cta"><h2>Turn this into your own departure plan</h2><p>Enter your actual flight date, free time, starting area and luggage. The planner checks a complete route; it does not supply live train departures.</p>'+cta+'</section></article></main>'
  text=re.sub(r'<main\b[^>]*>.*?</main>',lambda m:main,text,flags=re.S)
 text=update_meta(text,path,row)
 if path=='places/narita-omotesando':
  text=text.replace('https://www.nrtk.jp/translate/index.php?lang=en','https://www.japan.travel/en/spot/1549/')
 file.parent.mkdir(parents=True,exist_ok=True); file.write_text(text)

