for path in ['guides/index.html','index.html']:
 f=ROOT/path;t=f.read_text();t=re.sub(r'<!-- BYF:query-directory -->.*?<!-- /BYF:query-directory -->','',t,flags=re.S)
 t=t.replace('</main>','<!-- BYF:query-directory -->'+links+'<!-- /BYF:query-directory --></main>');f.write_text(t)
for path in ['places/haneda-airport/index.html','guides/haneda-departure-day/index.html','before-late-flight-tokyo/index.html']:
 f=ROOT/path;t=f.read_text();t=re.sub(r'<!-- BYF:haneda-answers -->.*?<!-- /BYF:haneda-answers -->','',t,flags=re.S)
 t=t.replace('</main>','<!-- BYF:haneda-answers --><section class="byf-next-decisions"><h2>Know your terminal before making plans</h2><ul><li>'+link('/guides/haneda-terminal-3-departure-guide/','Terminal 3: floors, map and departure procedures')+'</li><li>'+link('/guides/haneda-airport-open-24-hours/','Overnight and early flights: what is open at Haneda?')+'</li></ul></section><!-- /BYF:haneda-answers --></main>');f.write_text(t)
# New search URLs and real modification dates only.
f=ROOT/'sitemap.xml';t=f.read_text()
changed=set('/'+p+'/' for p in PAGES)|{'/','/guides/','/places/haneda-airport/','/guides/haneda-departure-day/','/before-late-flight-tokyo/'}
for path in changed:
 url=DOMAIN+path
 if '<loc>'+url+'</loc>' not in t:t=t.replace('</urlset>',f'<url><loc>{url}</loc><lastmod>{DATE}</lastmod></url>\n</urlset>')
 def replace(m):
  x=re.sub(r'<lastmod>.*?</lastmod>','',m[0]);return x.replace('</url>',f'<lastmod>{DATE}</lastmod></url>') if '<loc>'+url+'</loc>' in m[0] else m[0]
 t=re.sub(r'<url>.*?</url>',replace,t,flags=re.S)
f.write_text(t)
(ROOT/'audit/query-guides-manifest.json').write_text(json.dumps({'reviewed':DATE,'pages':[{'path':'/'+p+'/', 'title':r['title'],'sources':r['refs']} for p,r in PAGES.items()]},indent=2,ensure_ascii=False)+'\n')
print(f'Built {len(PAGES)} search-intent pages: 2 new guides and 10 refreshed pages across 10 initiatives.')
